<template><view class="destiny-edge" :class="{broken,flow:type==='CHOICE',trueRoute:type==='TRUE_ROUTE'}" :style="style"><AssetImage :src="broken?uiAssets.decorations.crack:uiAssets.decorations.line" fit="fill"/><view v-if="type==='CHOICE'||type==='TRUE_ROUTE'" class="flow-point"/></view></template><script setup lang="ts">import {computed} from 'vue';import AssetImage from '../common/AssetImage.vue';import {uiAssets} from '../../config/ui-assets';const props=defineProps<{from:{x:number;y:number};to:{x:number;y:number};broken?:boolean;type?:string}>();const style=computed(()=>({left:props.from.x+'px',top:props.from.y+'px',width:Math.hypot(props.to.x-props.from.x,props.to.y-props.from.y)+'px',transform:`rotate(${Math.atan2(props.to.y-props.from.y,props.to.x-props.from.x)}rad)`,color:props.broken?'#9b9b9b':props.type==='TRUE_ROUTE'?'#e5c982':props.type==='ENDING'?'#89b49b':props.type==='CHOICE'?'#c7a46d':'#8cabb9'}))</script><style scoped>.destiny-edge{position:absolute;height:1px;background:currentColor;transform-origin:0 50%;opacity:.33;pointer-events:none}.destiny-edge>.asset-image{position:absolute;inset:-2px 0;height:5px;opacity:.15}.broken{background:linear-gradient(90deg,currentColor 0 40%,transparent 40% 58%,currentColor 58%);opacity:.22}.flow-point{position:absolute;width:3px;height:3px;top:-1px;background:currentColor;border-radius:50%;animation:destiny-flow 7s linear infinite}.trueRoute{opacity:.55;box-shadow:0 0 3px #e5c98233}@media(prefers-reduced-motion:reduce){.flow-point{display:none}}</style>